# Section boundaries follow Markdown heading hierarchy. A parent section includes all children.
headings=[]
for i,line in enumerate(snap.splitlines()):
 m=re.match(r'^(#{1,6})\s+(.+?)\s*#*\s*$',line)
 if m: headings.append((i,len(m.group(1)),m.group(2)))
sections={}
lines=snap.splitlines()
for n,(start,level,title) in enumerate(headings):
 end=len(lines)
 for j,lvl,_ in headings[n+1:]:
  if lvl<=level: end=j; break
 sections[title]='\n'.join(lines[start:end]).rstrip()

def norm(x): return re.sub(r'[*_`]', '', x)
# Preserve literal source lines; manual fragments are only used to locate the controlling line.
def exact_lines(quote, section):
 body=sections[section]
 src=body.splitlines()
 out=[]
 for fragment in [x.strip() for x in quote.splitlines() if x.strip()]:
  nf=norm(fragment)
  candidates=[line for line in src if line.strip() and nf and nf in norm(line)]
  if not candidates:
   # Several source facts were written as short prompts that span more than one
   # source list item; map each to the closest unique literal controlling line.
   import difflib
   scored=sorted(((difflib.SequenceMatcher(None,nf,norm(line)).ratio(),line) for line in src if line.strip()),reverse=True)
   if not scored or scored[0][0]<0.34:
    raise RuntimeError(f'Cannot locate quote for {section}: {fragment[:100]!r}; best={scored[:1]}')
   candidates=[scored[0][1]]
  chosen=candidates[0]
  if chosen not in out: out.append(chosen)
 return out

# Resolve each authored citation to exact raw Markdown source lines.
resolved={}
for qid,pairs in A.items():
 citations=[]
 for fragment,heading in pairs:
  if heading not in sections: raise RuntimeError(f'unknown heading {heading!r} in {qid}; available={list(sections)}')
  for literal in exact_lines(fragment,heading):
   if literal not in [q for q,_ in citations]: citations.append((literal,heading))
 resolved[qid]=citations

