for item in questions:
 qid=item['id']
 if qid not in resolved: raise RuntimeError(f'missing {qid}')
 qlines=[q for q,_ in resolved[qid]]
 passages=[]; ev=[]
 for _,heading in resolved[qid]:
  if heading not in ev: ev.append(heading)
 for heading in ev: passages.append({'section':heading,'text':sections[heading]})
 for quote in qlines:
  if not any(quote in p['text'] for p in passages): raise RuntimeError(f'quote not contained: {qid} {quote[:80]}')
 ans={'id':qid,'answer':'\n\n'.join(qlines),'answer_quotations':qlines,'support_label':'supported','evidence':ev,'verbatim_passages':passages}
 if qid in numeric: ans['numeric_application']=numeric[qid]
 answers.append(ans)
assert [a['id'] for a in answers]==[q['id'] for q in questions]
assert len(answers)==104
assert all(a['answer']=='\n\n'.join(a['answer_quotations']) for a in answers)

